/* Generated by ADS from fonts.css and base.css: the fonts the first text uses. `ads assets` and the
   showcase and MCP server rewrite it; do not edit it. Call preloadFonts() in the app entry before
   the first render. */
import font0 from "../assets/fonts/Geist-Variable.woff2?url";

export const fontPreloads: readonly { readonly href: string; readonly type: string }[] = [
  { href: font0, type: "font/woff2" },
];

/** Adds one preload link per font. The crossorigin attribute matches how browsers fetch fonts. */
export function preloadFonts(): void {
  for (const { href, type } of fontPreloads) {
    const link = document.createElement("link");
    link.rel = "preload"; link.as = "font"; link.type = type; link.href = href; link.crossOrigin = "anonymous";
    document.head.append(link);
  }
}
